import BranchSelect from './components/BranchSelect.tsx';
import Panel from './components/Panel.tsx';
import ProductCard from './components/ProductCard.tsx';
import QuantityPicker from './components/QuantityPicker.tsx';
import StockBadge from './components/StockBadge.tsx';
import { NKWEN } from './data/nkwen.ts';

const rice = NKWEN.products[5];
const nothing = () => {};

export const good = [
  <StockBadge quantity={3} />,
  <Panel title="Hours"><p>7:30 to 19:00</p></Panel>,
  <ProductCard product={rice} branch="NKW" onAdd={(p) => p.name.toUpperCase()} />,
  <QuantityPicker label="Rice" value={2} max={10} onChange={(n) => n.toFixed(0)} />,
  <BranchSelect branches={NKWEN.branches} value="CAV" onChange={(code) => code.toLowerCase()} />,
];

export const bad = [
  // @ts-expect-error: quantity must be a number
  <StockBadge quantity="3" />,
  // @ts-expect-error: a Panel needs a title
  <Panel><p>no title</p></Panel>,
  // @ts-expect-error: a ProductCard needs a branch
  <ProductCard product={rice} onAdd={nothing} />,
  // @ts-expect-error: Limbe is not open, so it is not an OpenBranchCode
  <ProductCard product={rice} branch="LMB" onAdd={nothing} />,
  // @ts-expect-error: the value is a number, not text
  <QuantityPicker label="Rice" value="2" max={10} onChange={nothing} />,
  // @ts-expect-error: onChange receives a number, so it has no .toUpperCase()
  <QuantityPicker label="Rice" value={2} max={10} onChange={(n) => n.toUpperCase()} />,
  // @ts-expect-error: value must be an open branch code
  <BranchSelect branches={NKWEN.branches} value="Nkwen" onChange={nothing} />,
];
